// ───────────────────────────────────────────────────────────────────────────
// DEUTSCH — die erste Uebersetzung (E-28).
//
// Bis zum 2026-09-09 war Deutsch die Quellsprache dieses Repos und stand als
// Fallback im JSX; Englisch lag als Woerterbuch daneben. Seit E-28 ist es
// umgekehrt, und diese Datei ist das Ergebnis: dieselben Zeichenketten, nur
// auf der anderen Seite.
//
// DER WECHSEL WAR EIN TAUSCH UND KEINE UEBERSETZUNG. 4576 von 4577
// Schluesseln trugen bereits eine englische Fassung; jeder deutsche Text hier
// ist der, der vorher im JSX stand — Zeichen fuer Zeichen, geprueft im
// Rundlauf gegen den Stand davor. Wer hier etwas aendert, aendert die
// UEBERSETZUNG, nicht die Quelle.
//
// ELF SCHLUESSEL TRUGEN SCHON VORHER ZWEI VERSCHIEDENE DEUTSCHE FASSUNGEN an
// ihren beiden Aufrufstellen. Im Englischen zeigten beide denselben Eintrag —
// die Uneinigkeit war also nur im Deutschen sichtbar und ist erst beim Tausch
// aufgefallen. Entschieden hat die englische Fassung, weil sie fuer beide
// Stellen ohnehin schon galt. Zwei davon waren keine Uneinigkeit, sondern ein
// Fehler: `cable.field.notes` stand als „Notes" und `library.title` als
// „Library" im deutschen Fallback — ein deutscher Nutzer sah dort Englisch,
// und der Sprachschalter half nicht, weil der Fallback greift.
//
// WIE EINE WEITERE SPRACHE DAZUKOMMT: eine Datei wie diese anlegen und in
// `lib/i18n.ts` unter ihrem Kuerzel eintragen. Keine Zeile Logik.
// ───────────────────────────────────────────────────────────────────────────

