  // ── Ohne deutsche Fassung geblieben, jetzt uebersetzt (E-28) ────────────
  //
  // Diese vier standen nur im englischen Woerterbuch: sie kamen nach der
  // letzten Uebersetzungsrunde dazu (`analysis.crew.intro`,
  // `flags.patchPanelByCategory`) oder heute mit E-23
  // (`companion.optIn`, `delivery.osc.companionOptIn`). Solange Deutsch die
