  // sagt es.
  'analysis.crew.intro':
    'Stunden, Sätze und Auslagen für diesen Auftrag — und das Blatt, das sie in die Buchhaltung trägt. Überlappende Bänder stapeln sich NICHT: für jede Minute gilt der höchste Zuschlag. Überstunden und Bandzuschläge addieren sich dagegen SEHR WOHL — sie messen Verschiedenes. Die Ausrückpauschale gilt einmal je Person und Kalendertag, nicht je Eintrag. Eine Pause ist eine Lücke zwischen zwei Einträgen und kein Abzug: nur dann liegt jede Minute in ihrem echten Band.',
  'companion.optIn':
    'Companion: der SCHALT-Weg läuft über die HTTP-API (ab Werk an), das ZURÜCKLESEN über die TCP-Steuerung (bei einer Neuinstallation ab Werk aus, Port 16759; eine hochgezogene Installation hat sie an, auf Port 51234). Vor Ort nachsehen, nicht annehmen.',
